from algorithms import shortest_step
route = scan()
position = route["start"]
while position != route["goal"]:
    direction = shortest_step(route["board"], position, route["goal"])
    move(direction)
    if direction == "up":
        position[1] -= 1
    elif direction == "right":
        position[0] += 1
    elif direction == "down":
        position[1] += 1
    else:
        position[0] -= 1

